def read_first_line(filename):
    try:
        f = open(filename, 'r')
        return f.readline().strip()
    except FileNotFoundError:
        return 'File not found'
    finally:
        print('Clean-up: closing file')
        try:
            f.close()
        except NameError:
            pass

# Even if the function returns in try,
# finally runs before the return value is delivered

class CalculationError(Exception):
    pass

def calculate(a, op, b):
    if op == '+':
        return a + b
    elif op == '-':
        return a - b
    elif op == '*':
        return a * b
    elif op == '/':
        if b == 0:
            raise CalculationError('Division by zero')
        return a / b
    else:
        raise CalculationError(f'Unknown operator: {op}')

try:
    print(calculate(10, '+', 5))   # 15
    print(calculate(10, '/', 0))   # raises
except CalculationError as e:
    print(f'Error: {e}')

