class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount
        return f'Deposited ${amount}. Balance: ${self.balance}'

    def withdraw(self, amount):
        if amount > self.balance:
            return 'Insufficient funds!'
        self.balance -= amount
        return f'Withdrew ${amount}. Balance: ${self.balance}'

    def __str__(self):
        return f'Account of {self.owner}: ${self.balance}'

acc = BankAccount('Alice', 100)
print(acc.deposit(50))     # Deposited $50. Balance: $150
print(acc.withdraw(30))    # Withdrew $30. Balance: $120
print(acc.withdraw(200))   # Insufficient funds!
print(acc)                 # Account of Alice: $120

