class Vehicle:
    def __init__(self, brand, year):
        self.brand = brand
        self.year = year

    def info(self):
        return f'{self.brand} ({self.year})'

class Car(Vehicle):
    def __init__(self, brand, year, doors):
        super().__init__(brand, year)  # call parent's __init__
        self.doors = doors

    def info(self):
        return f'{super().info()} - {self.doors} doors'

car = Car('Toyota', 2020, 4)
print(car.info())  # Toyota (2020) - 4 doors

class Shape:
    def __init__(self, color='black'):
        self.color = color

    def area(self):
        """Must be overridden by subclasses."""
        raise NotImplementedError

    def __str__(self):
        return f'{self.color} shape'

class Circle(Shape):
    def __init__(self, radius, color='black'):
        super().__init__(color)
        self.radius = radius

    def area(self):
        return 3.14159 * self.radius ** 2

    def __str__(self):
        return f'{self.color} circle (r={self.radius})'

class Rectangle(Shape):
    def __init__(self, w, h, color='black'):
        super().__init__(color)
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h

shapes = [Circle(5, 'red'), Rectangle(4, 3, 'blue')]
for s in shapes:
    print(f'{s} has area {s.area()}')
# red circle (r=5) has area 78.53975
# blue shape has area 12

